1471:   new_addr_type mshr_addr = m_config.mshr_addr(mf->get_addr());
1472:   bool mshr_hit = m_mshrs.probe(mshr_addr);
1473:   bool mshr_avail = !m_mshrs.full(mshr_addr);
1474:   if (mshr_hit && mshr_avail) {
1475:     // A merge has no fill-owner of its own: the eventual lower response fills
1476:     // the cache index saved by the existing root request.  It is therefore
1477:     // valid only while that root's tag identity is still present.  Calling
1478:     // access() first on MISS/SECTOR_MISS would allocate a new RESERVED tag,
1479:     // then append this mf to the old MSHR; the old root fill would retire the
1480:     // MSHR/owner while leaving the new tag without a fill owner.  Probe before
1481:     // mutating the tag array and retry after the current MSHR drains instead.
1482:     enum cache_request_status merge_tag_status =
1483:         m_tag_array->probe(block_addr, cache_index, mf, mf->is_write());
1484:     if (merge_tag_status != HIT_RESERVED && merge_tag_status != HIT) {
1485:       return;
1486:     }
1487:     if (read_only)
1488:       m_tag_array->access(block_addr, time, cache_index, mf);
1489:     else
1490:       m_tag_array->access(block_addr, time, cache_index, wb, evicted, mf);
1491: 
1492:     m_mshrs.add(mshr_addr, mf);
1493:     m_stats.inc_stats(mf->get_access_type(), MSHR_HIT, mf->get_streamID());
1494:     do_miss = true;
1495: 
1496:   } else if (!mshr_hit && mshr_avail &&
